def broadcast(s1, s2):
    out = []
    for a, b in zip(reversed(s1), reversed(s2)):
        if a != b and 1 not in (a, b):
            return "error"
        out.append(max(a, b))
    longer = s1 if len(s1) > len(s2) else s2
    rest = list(longer[: len(longer) - len(out)])
    return tuple(rest + out[::-1])
